const size_t kStaStopCount = sizeof(kStaStops) / sizeof(kStaStops[0]);

const StopInfo* lookupStaStop(uint16_t stopCode) {
  size_t lo = 0;
  size_t hi = kStaStopCount;
  while (lo < hi) {
    size_t mid = lo + (hi - lo) / 2;
    if (kStaStops[mid].stopCode == stopCode) return &kStaStops[mid];
    if (kStaStops[mid].stopCode < stopCode) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  return nullptr;
}

